package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PositiveFactorListTest {
 private List<String> factors(int n){List<String> r=new ArrayList<>();for(int d=1;d<=n;d++)if(n%d==0)r.add(""+d);return r;}
 @Test public void everyNumberAndEachWrongEntryUsesPublicFactors(){Checker c=new Checker();for(int n=1;n<=100;n++){Question q=CompleteFactorPractice.make(CompleteFactorPractice.FACTORS,n,0);List<String> answer=factors(n);q.answers=new String[]{"poison"};q.expression="poison";assertTrue(c.check(q,List.of(),answer).correct());for(int i=0;i<answer.size();i++){List<String> wrong=new ArrayList<>(answer);wrong.set(i,"101");assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),wrong).status);assertEquals(i,c.check(q,List.of(),wrong).index);}List<String> duplicate=new ArrayList<>(answer);duplicate.add(answer.get(answer.size()-1));assertEquals("중복된 수 확인",c.check(q,List.of(),duplicate).message);if(answer.size()>1){assertEquals("빠진 약수 확인",c.check(q,List.of(),answer.subList(0,answer.size()-1)).message);List<String> reverse=new ArrayList<>(answer);Collections.reverse(reverse);assertEquals("작은 수부터 입력",c.check(q,List.of(),reverse).message);}assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("" )).status);}assertNull(CompleteFactorPractice.read(new Question(CompleteFactorPractice.FACTORS,"101의 약수를 모두 쓰세요.\n작은 수부터 쓰세요.","")));}
 @Test public void wholeGradeSixDomainIsFreshThenOldest(){String pack="na-nied-primary-2024-v1";Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,pack);assertTrue(GlobalCurriculum.pack(p).inGrade(CompleteFactorPractice.FACTORS,6));CurriculumLimits limits=GlobalCurriculum.limits(pack,CompleteFactorPractice.FACTORS,6);Generator g=new Generator(new Random(261));List<String> history=new ArrayList<>();Set<Integer> seen=new HashSet<>();for(int i=0;i<100;i++){Question q=g.next(CompleteFactorPractice.FACTORS,history,false,limits);assertFalse(history.contains(q.signature()));assertTrue(seen.add(CompleteFactorPractice.read(q)[0]));history.add(q.signature());}assertEquals(history.get(0),g.next(CompleteFactorPractice.FACTORS,history,false,limits).signature());}
 @Test public void pairsHelpChecksEveryBlankWithoutTransferAndSquaresAppearOnceInMain(){for(int n:new int[]{1,2,24,36,60,97,100}){Question q=CompleteFactorPractice.make(CompleteFactorPractice.FACTORS,n,0);HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int i=0;for(int d=1;d<=n;d++)if(n%d==0&&d<=n/d){assertTrue(h.step(i++).accepts(""+d));assertTrue(h.step(i++).accepts(""+(n/d)));assertTrue(h.step(i++).accepts(""+n));}assertEquals(i,h.size());assertTrue(new Checker().check(q,List.of(),factors(n)).correct());}}
}
